const p = await tools.update_plan({plan:[
  {step:"读取全局补充规范、项目 AGENTS.md 与 ROADMAP.md，确认 release 标准","status":"in_progress"},
  {step:"检查工作区、项目结构、依赖、配置与关键实现","status":"pending"},
  {step:"运行适用的测试、构建、lint/typecheck 与安全检查","status":"pending"},
  {step:"按严重级别汇总问题并给出是否可 release 的结论","status":"pending"}
]});
text(p);

const r = await tools.exec_command({
  cmd: "pwd && rg --files -g 'AGENTS.md' -g 'ROADMAP.md' -g '!node_modules' -g '!dist' -g '!build' | sort && sed -n '1,240p' ~/.codex/fable5-behavior-spec.md",
  workdir: "/Users/miykael/Documents/self/个人资料/en-app",
  yield_time_ms: 10000,
  max_output_tokens: 20000
});
text(r.output);

const r = await tools.exec_command({
  cmd: "sed -n '1,260p' ROADMAP.md && git status --short --branch && rg --files -g '!node_modules' -g '!dist' -g '!build' | sort | sed -n '1,260p'",
  workdir: "/Users/miykael/Documents/self/个人资料/en-app",
  yield_time_ms: 10000,
  max_output_tokens: 30000
});
text(r.output);

const r = await tools.exec_command({
  cmd: "sed -n '1,260p' README.md && sed -n '1,220p' frontend/package.json && sed -n '1,240p' backend/Cargo.toml && sed -n '1,260p' deploy/README.md && sed -n '1,260p' deploy/docker-compose.yml && git log --oneline --decorate -12 && git status --porcelain=v1",
  workdir: "/Users/miykael/Documents/self/个人资料/en-app",
  yield_time_ms: 10000,
  max_output_tokens: 30000
});
text(r.output);

const results = await Promise.all([
  tools.exec_command({cmd:"cargo test --all-targets && cargo clippy --all-targets -- -D warnings && cargo build --release",workdir:"/Users/miykael/Documents/self/个人资料/en-app/backend",yield_time_ms:1000,max_output_tokens:12000}),
  tools.exec_command({cmd:"npm run build && npm audit --omit=dev",workdir:"/Users/miykael/Documents/self/个人资料/en-app/frontend",yield_time_ms:1000,max_output_tokens:12000}),
  tools.exec_command({cmd:"python3 -m compileall -q services && docker compose -f deploy/docker-compose.yml config --quiet",workdir:"/Users/miykael/Documents/self/个人资料/en-app",yield_time_ms:1000,max_output_tokens:12000}),
  tools.exec_command({cmd:"rg -n --hidden -S '(TODO|FIXME|HACK|XXX|change-me|localhost|127\\.0\\.0\\.1|unwrap\\(|expect\\(|panic!|api[_-]?key|secret|token|password)' -g '!frontend/package-lock.json' -g '!.git/**' . && sed -n '1,240p' .gitignore && git show --stat --oneline HEAD && git show --format=fuller --no-ext-diff HEAD --",workdir:"/Users/miykael/Documents/self/个人资料/en-app",yield_time_ms:1000,max_output_tokens:20000})
]);
results.forEach((r,i)=>{ text(`---RESULT ${i+1}---\n${r.output}\nexit=${r.exit_code} session=${r.session_id??""}`); });

