+                r.try_get::<i64, _>("rec_count")?,
+                r.try_get::<i64, _>("screen_sec")?,
+                r.try_get::<i64, _>("frozen")?,
+            ),
+        );
+    }

-    let screen_sec_today: i64 = sqlx::query_scalar(
-        "SELECT COALESCE(screen_sec,0) FROM child_daily WHERE child_id=? AND day=?",
-    )
