+    let today_data = day_map.get(&today_str).copied().unwrap_or((0, 0, 0, 0));
+    let learned_today = today_data.0;
+    let rec_today = today_data.1;
+    let screen_sec_today = today_data.2;

     // 打卡：当天有学习或录音即算打卡日
     let checked_today = learned_today > 0 || rec_today > 0;
