# BabyEng TTS 推理服务（PRD 9.4：首选 Piper ONNX）
# 模型文件挂载到 /models/piper/，缺失时返回 503 由后端降级为「发音暂时不可用」（4.1.3）
# 依赖：pip install piper-tts fastapi uvicorn

import io
import os
import wave
from pathlib import Path

from fastapi import FastAPI, HTTPException, Query
from fastapi.responses import Response

app = FastAPI(title="BabyEng TTS", version="0.4.0")

MODEL_DIR = Path(os.environ.get("MODEL_DIR", "/models/piper"))
DEFAULT_VOICE = os.environ.get("PIPER_VOICE", "en_US-lessig-medium")

# 音色缓存：voice -> PiperVoice 实例
_voices = {}
_ready = False


def _load_voice(voice: str):
    """加载指定音色；成功返回实例，失败返回 None"""
    try:
        from piper import PiperVoice
    except ImportError:
        return None
    model_path = MODEL_DIR / f"{voice}.onnx"
    config_path = MODEL_DIR / f"{voice}.onnx.json"
    if not (model_path.exists() and config_path.exists()):
        return None
    try:
        return PiperVoice.load(str(model_path), str(config_path))
    except Exception as e:  # noqa: BLE001
        print(f"[tts] load {voice} failed: {e}")
        return None


def _any_model_available() -> bool:
    if not MODEL_DIR.exists():
        return False
    if not DEFAULT_VOICE:
        return False
    return (MODEL_DIR / f"{DEFAULT_VOICE}.onnx").exists()


_load_voice(DEFAULT_VOICE)
_ready = _any_model_available()


@app.get("/healthz")
def healthz():
    return {"ok": True}


@app.get("/readyz")
def readyz():
    return {"ok": _ready, "voice": DEFAULT_VOICE}


@app.get("/synthesize")
def synthesize(
    text: str = Query(...),
    voice: str = Query(DEFAULT_VOICE),
    length_scale: float = Query(0.8, ge=0.5, le=1.5),
):
    """合成文本 → 16k 单声道 wav。模型缺失 → 503（后端降级提示）"""
    if not _any_model_available():
        raise HTTPException(status_code=503, detail="tts model not ready")

    if voice not in _voices:
        v = _load_voice(voice)
        if v is None:
            raise HTTPException(status_code=503, detail=f"voice {voice} not available")
        _voices[voice] = v
    v = _voices[voice]

    wav_bytes = io.BytesIO()
    try:
        with wave.open(wav_bytes, "wb") as f:
            v.synthesize(text, f, length_scale=length_scale)
    except Exception as e:  # noqa: BLE001
        raise HTTPException(status_code=500, detail=f"synthesize error: {e}")
    return Response(
        content=wav_bytes.getvalue(),
        media_type="audio/wav",
        headers={"Cache-Control": "no-cache"},
    )


if __name__ == "__main__":
    import uvicorn

    uvicorn.run(app, host="0.0.0.0", port=int(os.environ.get("PORT", "8101")))
# BabyEng ASR 推理服务（PRD 9.5：首选 sherpa-onnx 流式中文模型）
# 模型文件挂载到 /models/asr/，缺失时返回 503 由后端降级为「没听清，可以打字」（5.4）
# 依赖：pip install sherpa-onnx fastapi uvicorn
# 契约：POST /recognize，Content-Type: audio/wav，body 为 16k 单声道 wav（后端已用 ffmpeg 转码）

import os
from pathlib import Path

import numpy as np
from fastapi import FastAPI, HTTPException, Request
from fastapi.responses import JSONResponse

app = FastAPI(title="BabyEng ASR", version="0.4.0")

MODEL_DIR = Path(os.environ.get("MODEL_DIR", "/models/asr"))

# sherpa-onnx 流式中文模型（zipformer bilingual zh-en 等）
MODEL_NAME = os.environ.get("ASR_MODEL", "sherpa-onnx-streaming-zipformer-bilingual-zh-en-2023-02-20")

_recognizer = None
_ready = False


def _load():
    global _recognizer, _ready
    try:
        import sherpa_onnx

        tokens = MODEL_DIR / MODEL_NAME / "tokens.txt"
        encoder = MODEL_DIR / MODEL_NAME / "encoder-epoch-99-avg-1.onnx"
        decoder = MODEL_DIR / MODEL_NAME / "decoder-epoch-99-avg-1.onnx"
        joiner = MODEL_DIR / MODEL_NAME / "joiner-epoch-99-avg-1.onnx"
        if not all(p.exists() for p in (tokens, encoder, decoder, joiner)):
            _ready = False
            return

        recognizer = sherpa_onnx.OnlineRecognizer.from_transducer(
            tokens=str(tokens),
            encoder=str(encoder),
            decoder=str(decoder),
            joiner=str(joiner),
            num_threads=2,
            sample_rate=16000,
            feature_dim=80,
            enable_endpoint_detection=True,
            rule1_min_trailing_silence=2.4,
            rule2_min_trailing_silence=1.2,
            rule3_min_utterance_length=300,
        )
        _recognizer = recognizer
        _ready = True
    except Exception as e:  # noqa: BLE001
        print(f"[asr] load failed: {e}")
        _recognizer = None
        _ready = False


_load()


@app.get("/healthz")
def healthz():
    return {"ok": True}


@app.get("/readyz")
def readyz():
    return {"ok": _ready}


@app.post("/recognize")
async def recognize(request: Request):
    """16k 单声道 wav → 中文文本 + 置信度。模型缺失 → 503"""
    if not _ready:
        raise HTTPException(status_code=503, detail="asr model not ready")
    body = await request.body()
    if len(body) < 44:
        raise HTTPException(status_code=400, detail="wav too short")

    # 解析 wav 头
    sample_rate = int.from_bytes(body[24:28], "little")
    channels = int.from_bytes(body[22:24], "little")
    if sample_rate != 16000:
        # 宽松：若采样率不符，重采样代价高，先按 16k 读（后端已保证 16k）
        pass

    samples = np.frombuffer(body[44:], dtype=np.int16).astype(np.float32) / 32768.0
    stream = _recognizer.create_stream()
    # 分块喂入（模拟流式）
    chunk = 1600  # 0.1s
    for i in range(0, len(samples), chunk):
        stream.accept_waveform(16000, samples[i : i + chunk].tolist())
    _recognizer.decode_stream(stream)

    text = stream.result.text.strip()
    # 置信度：本实现给出启发式（非空文本 0.8，空文本 0.0）
    confidence = 0.8 if text else 0.0
    return JSONResponse({"text": text, "confidence": confidence})


if __name__ == "__main__":
    import uvicorn

    uvicorn.run(app, host="0.0.0.0", port=int(os.environ.get("PORT", "8102")))
