  childUpdate: (childId, data) => request(`/family/child/${childId}`, { method: 'PUT', body: JSON.stringify(data) }),

  // ---------- 问答（M1） ----------
  askText: (text, opts = {}) =>
    request('/ask/text', { method: 'POST', body: JSON.stringify({ text, ...opts }) }),
  askVoice: (blob, fileName, childId, familyId) => {
