async fn child_update(
    State(state): State<SharedState>,
    Path(child_id): Path<String>,
    Json(body): Json<ChildUpdate>,
) -> AppResult<Json<serde_json::Value>> {
    let pool = &state.pool;
    if let Some(name) = &body.child_name {
        sqlx::query("UPDATE child SET child_name=? WHERE child_id=?")
            .bind(name)
            .bind(&child_id)
            .execute(pool)
            .await?;
    }
    if let Some(bd) = &body.child_birthdate {
        sqlx::query("UPDATE child SET child_birthdate=? WHERE child_id=?")
            .bind(bd)
            .bind(&child_id)
            .execute(pool)
            .await?;
    }
    if let Some(band) = &body.age_band_override {
        let band = if band.is_empty() { None } else { Some(band.clone()) };
        sqlx::query("UPDATE child SET age_band_override=? WHERE child_id=?")
            .bind(band)
            .bind(&child_id)
            .execute(pool)
            .await?;
    }
    if let Some(lv) = body.level {
        sqlx::query("UPDATE child SET level=? WHERE child_id=?")
            .bind(lv)
            .bind(&child_id)
            .execute(pool)
            .await?;
    }
    Ok(Json(json!({ "ok": true })))
}

async fn child_get(State(state): State<SharedState>, Path(child_id): Path<String>) -> AppResult<Json<serde_json::Value>> {
    let pool = &state.pool;
    let child = sqlx::query_as::<_, (String, String, String, Option<String>, Option<String>, i64)>(
        "SELECT child_id, family_id, child_name, child_birthdate, age_band_override, level FROM child WHERE child_id=?",
    )
    .bind(&child_id)
    .fetch_optional(pool)
    .await?
    .map(|(child_id, family_id, child_name, child_birthdate, age_band_override, level)| Child {
        child_id,
        family_id,
        child_name,
        child_birthdate,
        age_band_override,
        level,
    });
    let Some(child) = child else {
        return Err(AppError::NotFound("孩子不存在".into()));
    };
    let band = child
        .age_band_override
        .clone()
        .or_else(|| {
            AgeBand::from_birthdate(child.child_birthdate.as_deref(), &chrono::Utc::now())
                .map(|b| b.label().to_string())
        });
    Ok(Json(json!({
        "child": child,
        "age_band": band,
    })))
}
//! 配置加载（env 驱动，PRD 9.9：.env 管理 secret 与服务地址）

use std::env;

#[derive(Debug, Clone)]
pub struct Config {
    /// 监听地址，默认 0.0.0.0:8080
    pub bind_addr: String,
    /// SQLite 文件路径
    pub database_url: String,
    /// 词条 seed 目录（JSON 文件）
    pub seed_dir: String,
    /// 录音与音频缓存根目录
    pub audio_dir: String,
    /// 推理服务地址（HTTP）
    pub tts_url: String,
    pub asr_url: String,
    pub llm_url: String,
    /// 主密钥（用于 API Key envelope 加密；开发默认随机，重启即失效）
    pub master_key: String,
    /// 音频转码可执行文件
    pub ffmpeg_bin: String,
    /// 静态前端目录（PWA 产物）
    pub static_dir: String,
    /// 推理服务调用超时（秒）
    pub svc_timeout_secs: u64,
}

impl Config {
    pub fn from_env() -> Self {
        Self {
            bind_addr: env::var("BIND_ADDR").unwrap_or_else(|_| "0.0.0.0:8080".into()),
            database_url: env::var("DATABASE_URL")
                .unwrap_or_else(|_| "sqlite://data/babyeng.db".into()),
            seed_dir: env::var("SEED_DIR").unwrap_or_else(|_| "data/seed".into()),
            audio_dir: env::var("AUDIO_DIR").unwrap_or_else(|_| "data/audio".into()),
            tts_url: env::var("TTS_URL").unwrap_or_else(|_| "http://127.0.0.1:8101".into()),
            asr_url: env::var("ASR_URL").unwrap_or_else(|_| "http://127.0.0.1:8102".into()),
            llm_url: env::var("LLM_URL").unwrap_or_else(|_| "http://127.0.0.1:8103".into()),
            master_key: env::var("MASTER_KEY").unwrap_or_else(|_| "dev-insecure-key".into()),
            ffmpeg_bin: env::var("FFMPEG_BIN").unwrap_or_else(|_| "ffmpeg".into()),
            static_dir: env::var("STATIC_DIR").unwrap_or_else(|_| "frontend/dist".into()),
            svc_timeout_secs: env::var("SVC_TIMEOUT_SECS")
                .ok()
                .and_then(|v| v.parse().ok())
                .unwrap_or(10),
        }
    }
}
-- BabyEng 数据库初始化（PRD 第 8 章 + 9.8）
-- SQLite / sqlx migrate

-- ---------- 家庭与孩子（8.5 / 9.8） ----------
CREATE TABLE family (
  family_id   TEXT PRIMARY KEY,
  mother_name TEXT NOT NULL DEFAULT '',
  settings    TEXT NOT NULL DEFAULT '{}',          -- json: 语速、屏幕时间上限、纯音频开关等家庭级设置
  created_at  TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ','now'))
);

CREATE TABLE child (
  child_id          TEXT PRIMARY KEY,
  family_id         TEXT NOT NULL REFERENCES family(family_id),
  child_name        TEXT NOT NULL DEFAULT '',
  child_birthdate   TEXT,                            -- YYYY-MM-DD，用于推导 A/B 分段
  age_band_override TEXT,                            -- 'A' / 'B' / NULL（母亲手动覆盖）
  level             INTEGER NOT NULL DEFAULT 1,      -- 1/2/3
  created_at        TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ','now'))
);
CREATE INDEX idx_child_family ON child(family_id);

-- ---------- 词条 Word（8.1） ----------
CREATE TABLE word (
  id              TEXT PRIMARY KEY,                  -- 如 word_cup
  zh              TEXT NOT NULL,
  aliases         TEXT NOT NULL DEFAULT '[]',        -- json 数组，不可为空（匹配管线 L1 依赖）
  en              TEXT NOT NULL,
  pos             TEXT NOT NULL DEFAULT 'noun',
  phonetic        TEXT,                              -- 美式 IPA，如 /kʌp/；空表示「音标待确认」
  phonetic_source TEXT NOT NULL DEFAULT 'manual',    -- dict / g2p / manual，绝不含 llm（4.1.2）
  category        TEXT NOT NULL,                     -- item_furniture / person_family / number / emotion ...
  level           INTEGER NOT NULL DEFAULT 1,
  image_emoji     TEXT NOT NULL DEFAULT '',          -- 开发期占位（3.7：最终用自家实物照片）
  image_source    TEXT NOT NULL DEFAULT 'family',    -- family / cc0 / generated
  tts_audio_path  TEXT,
  tts_voice       TEXT,
  example_en      TEXT,
  example_zh      TEXT,
  mother_tip      TEXT,                              -- 母亲学习卡（M9）
  review_status   TEXT NOT NULL DEFAULT 'draft',     -- draft / audio_ok / published，未校音不下发
  created_at      TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ','now'))
);

-- ---------- 句子 Sentence（8.2） ----------
CREATE TABLE sentence (
  id               TEXT PRIMARY KEY,
  zh               TEXT NOT NULL,
  aliases          TEXT NOT NULL DEFAULT '[]',
  en               TEXT NOT NULL,
  phonetic         TEXT,
  phonetic_source  TEXT NOT NULL DEFAULT 'manual',
  scene            TEXT NOT NULL,                    -- morning / meal / play / bedtime / outing
  tts_audio_path   TEXT,
  tts_voice        TEXT,
  example_context  TEXT,                             -- 使用场景说明
  review_status    TEXT NOT NULL DEFAULT 'draft',
  created_at       TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ','now'))
);

-- ---------- 别名展开表（8.9：L1 精确匹配的检索表，唯一索引） ----------
CREATE TABLE word_alias (
  alias   TEXT NOT NULL,
  word_id TEXT NOT NULL,
  PRIMARY KEY (alias, word_id)
);
CREATE INDEX idx_word_alias_word ON word_alias(word_id);

CREATE TABLE sentence_alias (
  alias       TEXT NOT NULL,
  sentence_id TEXT NOT NULL,
  PRIMARY KEY (alias, sentence_id)
);
CREATE INDEX idx_sentence_alias_sent ON sentence_alias(sentence_id);

-- ---------- 学习记录 LearningRecord（8.3，明细流水） ----------
CREATE TABLE learning_record (
  id           TEXT PRIMARY KEY,
  child_id     TEXT NOT NULL REFERENCES child(child_id),
  target_type  TEXT NOT NULL,                        -- word / sentence
  target_id    TEXT NOT NULL,
  action       TEXT NOT NULL,                        -- learn / review / quiz / ask
  mother_mark  TEXT,                                 -- got_it / keep_trying / null
  quiz_result  TEXT,                                 -- 仅 quiz：correct / wrong / skipped
  recorded_at  TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ','now'))
);
CREATE INDEX idx_learnrec_child_time ON learning_record(child_id, recorded_at);

-- ---------- 录音 Recording（8.4） ----------
CREATE TABLE recording (
  id          TEXT PRIMARY KEY,
  child_id    TEXT NOT NULL REFERENCES child(child_id),
  target_type TEXT NOT NULL,
  target_id   TEXT NOT NULL,
  audio_path  TEXT NOT NULL,
  duration_ms INTEGER NOT NULL DEFAULT 0,
  similarity  REAL,                                  -- 保留可空，MVP/V1 不写入（4.3）
  favorited   INTEGER NOT NULL DEFAULT 0,
  created_at  TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ','now')),
  expires_at  TEXT NOT NULL                          -- 默认 +30 天
);
CREATE INDEX idx_rec_child_time ON recording(child_id, created_at);
CREATE INDEX idx_rec_expires ON recording(expires_at);

-- ---------- 学习进度 Progress（8.6） ----------
CREATE TABLE progress (
  child_id         TEXT NOT NULL,
  target_type      TEXT NOT NULL,
  target_id        TEXT NOT NULL,
  learn_count      INTEGER NOT NULL DEFAULT 0,
  review_count     INTEGER NOT NULL DEFAULT 0,
  last_mother_marks  TEXT NOT NULL DEFAULT '[]',     -- json 最近 3 次
  last_quiz_results  TEXT NOT NULL DEFAULT '[]',     -- json 最近 3 次（仅 B 段）
  last_touched_at  TEXT,
  next_review_at   TEXT,
  mastery          REAL NOT NULL DEFAULT 0,
  PRIMARY KEY (child_id, target_type, target_id)
);
CREATE INDEX idx_progress_review ON progress(child_id, next_review_at);

-- ---------- 成就 Achievement（8.7） ----------
CREATE TABLE achievement (
  id          TEXT PRIMARY KEY,
  child_id    TEXT NOT NULL REFERENCES child(child_id),
  type        TEXT NOT NULL,                         -- medal / streak / stars
  key         TEXT NOT NULL,                         -- 如 scene_item_done / streak_7
  unlocked_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ','now'))
);
CREATE UNIQUE INDEX idx_achievement_unique ON achievement(child_id, key);

-- ---------- 未命中查询 UnmatchedQuery（8.8，词库扩充输入源） ----------
CREATE TABLE unmatched_query (
  id                TEXT PRIMARY KEY,
  family_id         TEXT NOT NULL REFERENCES family(family_id),
  raw_text          TEXT NOT NULL,
  normalized_text   TEXT NOT NULL,
  asr_confidence    REAL,
  llm_result        TEXT,                            -- json，若走到 L4
  hit_count         INTEGER NOT NULL DEFAULT 1,
  status            TEXT NOT NULL DEFAULT 'pending', -- pending / adopted / rejected
  last_seen_at      TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ','now'))
);
CREATE UNIQUE INDEX idx_unmatched_norm ON unmatched_query(family_id, normalized_text);

-- ---------- 模型配置（9.8） ----------
CREATE TABLE model_config (
  config_id   TEXT PRIMARY KEY,
  family_id   TEXT NOT NULL REFERENCES family(family_id),
  type        TEXT NOT NULL,                         -- llm / tts / asr
  provider    TEXT NOT NULL,                         -- local / openai / ollama
  model_name  TEXT NOT NULL DEFAULT '',
  endpoint    TEXT,
  api_key_enc TEXT,                                  -- 服务器主密钥 envelope 加密（9.10）
  params      TEXT NOT NULL DEFAULT '{}',
  created_at  TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ','now'))
);

CREATE TABLE family_model_binding (
  family_id     TEXT PRIMARY KEY REFERENCES family(family_id),
  llm_config_id TEXT,
  tts_config_id TEXT,
  asr_config_id TEXT
);

-- ---------- 应用元数据 ----------
CREATE TABLE app_meta (
  key   TEXT PRIMARY KEY,
  value TEXT NOT NULL
);
INSERT INTO app_meta(key, value) VALUES ('schema_version', '1');
-- 每日统计表：打卡（7.1）、Streak Freeze、日报（7.3）、屏幕时间（11.3）
CREATE TABLE IF NOT EXISTS child_daily (
  child_id   TEXT NOT NULL,
  day        TEXT NOT NULL,                -- 本地日期 YYYY-MM-DD
  learn_count  INTEGER NOT NULL DEFAULT 0, -- 当日学习词数
  rec_count    INTEGER NOT NULL DEFAULT 0, -- 当日跟读录音次数
  rec_ms       INTEGER NOT NULL DEFAULT 0, -- 当日录音总毫秒（亲子学习时长）
  screen_sec   INTEGER NOT NULL DEFAULT 0, -- 当日幼儿屏幕时长（纯音频不计入）
  frozen       INTEGER NOT NULL DEFAULT 0, -- 当日是否使用打卡保护
  PRIMARY KEY (child_id, day)
);
CREATE INDEX IF NOT EXISTS idx_child_daily_child ON child_daily(child_id, day);

