//! M3 录音（PRD 4.3 / 8.4）：上传、回放、收藏、过期清理、30 天保留

use axum::extract::{Multipart, Path, Query, State};
use axum::http::header;
use axum::routing::{delete, get, post};
use axum::{Json, Router};
use chrono::{Duration, Local};
use serde::Deserialize;
use serde_json::json;
use sqlx::Row;
use uuid::Uuid;

use crate::error::{AppError, AppResult};
use crate::state::SharedState;

pub fn router() -> Router<SharedState> {
    Router::new()
        .route("/api/recordings", get(list))
        .route("/api/recordings", post(upload))
        .route("/api/recordings/{id}", delete(remove))
        .route("/api/recordings/{id}/favorite", post(favorite))
        .route("/api/recordings/{id}/audio", get(audio))
        .route("/api/recordings/cleanup-expired", post(cleanup_expired))
}

#[derive(Deserialize)]
struct ListQuery {
    child_id: Option<String>,
}

async fn list(State(state): State<SharedState>, Query(q): Query<ListQuery>) -> AppResult<Json<serde_json::Value>> {
    let pool = &state.pool;
    let mut sql = String::from(
        "SELECT id, child_id, target_type, target_id, audio_path, duration_ms, favorited, created_at, expires_at FROM recording",
    );
    if let Some(cid) = &q.child_id {
        sql.push_str(&format!(" WHERE child_id='{}'", cid));
    }
    sql.push_str(" ORDER BY created_at DESC LIMIT 100");
    let rows = sqlx::query(&sql).fetch_all(pool).await?;

    let mut out = Vec::new();
    for r in &rows {
        out.push(json!({
            "id": r.try_get::<String, _>("id")?,
            "child_id": r.try_get::<String, _>("child_id")?,
            "target_type": r.try_get::<String, _>("target_type")?,
            "target_id": r.try_get::<String, _>("target_id")?,
            "duration_ms": r.try_get::<i64, _>("duration_ms")?,
            "favorited": r.try_get::<i64, _>("favorited")? > 0,
            "created_at": r.try_get::<String, _>("created_at")?,
            "expires_at": r.try_get::<String, _>("expires_at")?,
        }));
    }
    Ok(Json(json!({ "recordings": out })))
}

/// 上传录音（webm/opus 或 mp4/aac，落盘即存，PRD 9.2：不在前端长期堆积）
async fn upload(
    State(state): State<SharedState>,
    mut multipart: Multipart,
) -> AppResult<Json<serde_json::Value>> {
    let mut audio: Option<Vec<u8>> = None;
    let mut ext = "webm".to_string();
    let mut child_id: Option<String> = None;
    let mut target_type = "word".to_string();
    let mut target_id = String::new();
    let mut duration_ms: i64 = 0;

    while let Some(field) = multipart.next_field().await.map_err(|_| AppError::BadRequest("multipart 解析失败".into()))? {
        match field.name().unwrap_or("") {
            "audio" => {
                ext = field
                    .content_type()
                    .map(|t| {
                        if t.contains("mp4") || t.contains("aac") || t.contains("m4a") {
                            "m4a"
                        } else if t.contains("ogg") {
                            "ogg"
                        } else {
                            "webm"
                        }
                    })
                    .unwrap_or("webm")
                    .to_string();
                audio = Some(field.bytes().await.map_err(|_| AppError::BadRequest("读取音频失败".into()))?.to_vec());
            }
            "child_id" => child_id = field.text().await.ok(),
            "target_type" => target_type = field.text().await.unwrap_or_else(|_| "word".into()),
            "target_id" => target_id = field.text().await.unwrap_or_default(),
            "duration_ms" => duration_ms = field.text().await.ok().and_then(|s| s.parse().ok()).unwrap_or(0),
            _ => {}
        }
    }

    let Some(audio) = audio else {
        return Err(AppError::BadRequest("缺少 audio 字段".into()));
    };
    let Some(child_id) = child_id else {
        return Err(AppError::BadRequest("缺少 child_id".into()));
    };
    if target_id.is_empty() {
        return Err(AppError::BadRequest("缺少 target_id".into()));
    }

    // PRD 4.3 / 5.4：< 0.5s 不入库、不计学习记录
    if duration_ms > 0 && duration_ms < 500 {
        return Err(AppError::BadRequest("录音过短".into()));
    }

    let rec_id = Uuid::new_v4().to_string();
    let dir = format!("{}/recordings", state.cfg.audio_dir);
    std::fs::create_dir_all(&dir)?;
    let file_name = format!("{}.{}", rec_id, ext);
    let path = format!("{}/{}", dir, file_name);
    std::fs::write(&path, &audio)?;

    let now = chrono::Utc::now();
    let expires = now + Duration::days(30); // 默认 30 天过期（8.4）
    sqlx::query(
        "INSERT INTO recording (id, child_id, target_type, target_id, audio_path, duration_ms, favorited, created_at, expires_at) \
         VALUES (?,?,?,?,?,?,0,?,?)",
    )
    .bind(&rec_id)
    .bind(&child_id)
    .bind(&target_type)
    .bind(&target_id)
    .bind(&path)
    .bind(duration_ms)
    .bind(now.to_rfc3339())
    .bind(expires.to_rfc3339())
    .execute(&state.pool)
    .await?;

    // 当日统计 + 打卡（7.1）
    crate::logic::bump_recording(&state.pool, &child_id, duration_ms).await?;

    Ok(Json(json!({
        "ok": true,
        "recording_id": rec_id,
        "duration_ms": duration_ms,
        "expires_at": expires.to_rfc3339(),
    })))
}

async fn favorite(
    State(state): State<SharedState>,
    Path(id): Path<String>,
    Query(q): Query<serde_json::Value>,
) -> AppResult<Json<serde_json::Value>> {
    let fav = q
        .get("favorited")
        .and_then(|v| v.as_bool())
        .unwrap_or(true);
    let rows = sqlx::query("UPDATE recording SET favorited=? WHERE id=?")
        .bind(fav as i64)
        .bind(&id)
        .execute(&state.pool)
        .await?;
    if rows.rows_affected() == 0 {
        return Err(AppError::NotFound("录音不存在".into()));
    }
    Ok(Json(json!({ "ok": true, "favorited": fav })))
}

async fn remove(State(state): State<SharedState>, Path(id): Path<String>) -> AppResult<Json<serde_json::Value>> {
    let pool = &state.pool;
    let row = sqlx::query_as::<_, (String,)>("SELECT audio_path FROM recording WHERE id=?")
        .bind(&id)
        .fetch_optional(pool)
        .await?;
    let Some((path,)) = row else {
        return Err(AppError::NotFound("录音不存在".into()));
    };
    let _ = std::fs::remove_file(&path);
    sqlx::query("DELETE FROM recording WHERE id=?").bind(&id).execute(pool).await?;
    Ok(Json(json!({ "ok": true })))
}

/// 回放音频（文件流式返回）
async fn audio(State(state): State<SharedState>, Path(id): Path<String>) -> AppResult<axum::response::Response> {
    let row = sqlx::query_as::<_, (String,)>("SELECT audio_path FROM recording WHERE id=?")
        .bind(&id)
        .fetch_optional(&state.pool)
        .await?;
    let Some((path,)) = row else {
        return Err(AppError::NotFound("录音不存在".into()));
    };
    let bytes = std::fs::read(&path)?;
    let mime = if path.ends_with(".m4a") || path.ends_with(".aac") {
        "audio/mp4"
    } else if path.ends_with(".ogg") {
        "audio/ogg"
    } else {
        "audio/webm"
    };
    let mut resp = axum::response::Response::new(axum::body::Body::from(bytes));
    resp.headers_mut().insert(header::CONTENT_TYPE, header::HeaderValue::from_static(mime));
    Ok(resp)
}

/// 过期清理（30 天前非收藏，PRD 5.4 / 8.4）：设置页一键清理入口
async fn cleanup_expired(State(state): State<SharedState>) -> AppResult<Json<serde_json::Value>> {
    let pool = &state.pool;
    let cutoff = (Local::now() - Duration::days(30)).format("%Y-%m-%dT%H:%M:%SZ").to_string();
    let rows = sqlx::query_as::<_, (String, String)>(
        "SELECT id, audio_path FROM recording WHERE expires_at < ? AND favorited = 0",
    )
    .bind(&cutoff)
    .fetch_all(pool)
    .await?;
    let mut freed = 0usize;
    for (id, path) in rows {
        if let Ok(md) = std::fs::metadata(&path) {
            freed += md.len() as usize;
        }
        let _ = std::fs::remove_file(&path);
        sqlx::query("DELETE FROM recording WHERE id=?").bind(&id).execute(pool).await?;
    }
    Ok(Json(json!({ "ok": true, "cleaned": freed, "freed_bytes": freed })))
}
//! M1 语音问答主链路（PRD 4.1 / 4.1.1~4.1.3 / 5.3 / 6.1）
//! 文本提问 / 语音提问（ASR）→ 匹配管线 L0~L2 → TTS → 结果卡
//! 彻底未命中：相近词推荐 + 文字输入 + 静默写入 unmatched_query（8.8）
//! ASR/TTS 不可用：分别降级（4.1.3 / 5.4），不整页报错

use axum::extract::{Multipart, Query, State};
use axum::routing::post;
use axum::{Json, Router};
use serde::Deserialize;
use serde_json::json;
use uuid::Uuid;

use crate::error::{AppError, AppResult};
use crate::matcher::Match;
use crate::models::{AskResponse, AskResult};
use crate::state::SharedState;
use crate::store;

pub fn router() -> Router<SharedState> {
    Router::new()
        .route("/api/ask/text", post(ask_text))
        .route("/api/ask/voice", post(ask_voice))
        .route("/api/ask/confirm", post(ask_confirm))
}

#[derive(Deserialize)]
struct AskTextBody {
    text: String,
    child_id: Option<String>,
    family_id: Option<String>,
    /// ASR 置信度（语音链路透传，用于未命中表归组，8.8）
    asr_confidence: Option<f64>,
}

async fn ask_text(State(state): State<SharedState>, Json(body): Json<AskTextBody>) -> AppResult<Json<AskResponse>> {
    let text = body.text.trim().to_string();
    if text.is_empty() {
        return Err(AppError::BadRequest("文本为空".into()));
    }
    let resp = run_pipeline(&state, &text, body.asr_confidence, body.family_id.as_deref(), body.child_id.as_deref()).await;
    Ok(Json(resp))
}

/// 语音提问：multipart 上传音频 → ffmpeg 转 16k wav → ASR → 匹配
async fn ask_voice(
    State(state): State<SharedState>,
    mut multipart: Multipart,
) -> AppResult<Json<AskResponse>> {
    let mut audio_bytes: Option<Vec<u8>> = None;
    let mut ext = "webm".to_string();
    let mut child_id: Option<String> = None;
    let mut family_id: Option<String> = None;

    while let Some(field) = multipart
        .next_field()
        .await
        .map_err(|_| AppError::BadRequest("multipart 解析失败".into()))?
    {
        let name = field.name().unwrap_or("").to_string();
        match name.as_str() {
            "audio" => {
                ext = field
                    .content_type()
                    .and_then(|t| {
                        if t.contains("mp4") || t.contains("aac") || t.contains("m4a") {
                            Some("m4a")
                        } else if t.contains("ogg") {
                            Some("ogg")
                        } else {
                            Some("webm")
                        }
                    })
                    .unwrap_or("webm")
                    .to_string();
                let data = field
                    .bytes()
                    .await
                    .map_err(|_| AppError::BadRequest("读取音频失败".into()))?;
                audio_bytes = Some(data.to_vec());
            }
            "child_id" => {
                child_id = field.text().await.ok();
            }
            "family_id" => {
                family_id = field.text().await.ok();
            }
            _ => {}
        }
    }

    let Some(audio) = audio_bytes else {
        return Err(AppError::BadRequest("缺少 audio 字段".into()));
    };

    // 1. 转码 16k 单声道 wav（9.10：Android webm/opus、iOS mp4/aac 都转）
    let wav = state.inference.to_wav_16k(audio, ext).await?;
    // 2. ASR（不可用 → 明确降级：asr_fail，前端给「没听清/打字」兜底）
    let outcome = match state.inference.asr_recognize(wav).await {
        Ok(o) => o,
        Err(AppError::AsrUnavailable) => {
            return Ok(Json(AskResponse {
                status: "asr_fail".into(),
                result: None,
                candidates: vec![],
                recognized_text: None,
                normalized_text: None,
                unmatched_id: None,
                message: Some("识别服务暂时不可用，可以打字提问".into()),
            }));
        }
        Err(e) => return Err(e),
    };

    let text = outcome.text.trim().to_string();
    if text.is_empty() {
        return Ok(Json(AskResponse {
            status: "asr_fail".into(),
            result: None,
            candidates: vec![],
            recognized_text: Some(String::new()),
            normalized_text: None,
            unmatched_id: None,
            message: Some("没听清，再说一次".into()),
        }));
    }

    let resp = run_pipeline(&state, &text, outcome.confidence, family_id.as_deref(), child_id.as_deref()).await;
    Ok(Json(resp))
}

/// 二选一确认（PRD 4.1：你是说 A 还是 B？）
#[derive(Deserialize)]
struct ConfirmBody {
    target_type: String,
    target_id: String,
    child_id: Option<String>,
}

async fn ask_confirm(State(state): State<SharedState>, Json(body): Json<ConfirmBody>) -> AppResult<Json<serde_json::Value>> {
    let pool = &state.pool;
    let result = match body.target_type.as_str() {
        "word" => {
            let w = store::get_word(pool, &body.target_id).await?;
            let Some(w) = w else {
                return Err(AppError::NotFound("词条不存在".into()));
            };
            AskResult {
                target_type: "word".into(),
                target_id: w.id.clone(),
                zh: w.zh,
                en: w.en,
                phonetic: w.phonetic,
                phonetic_source: Some(w.phonetic_source),
                category: Some(w.category),
                scene: None,
                example_en: w.example_en,
                example_zh: w.example_zh,
                example_context: None,
                mother_tip: w.mother_tip,
                image_emoji: Some(w.image_emoji),
                match_level: "L2-confirm".into(),
                tts_available: false,
                tts_url: None,
            }
        }
        "sentence" => {
            let s = store::get_sentence(pool, &body.target_id).await?;
            let Some(s) = s else {
                return Err(AppError::NotFound("句子不存在".into()));
            };
            AskResult {
                target_type: "sentence".into(),
                target_id: s.id.clone(),
                zh: s.zh,
                en: s.en,
                phonetic: s.phonetic,
                phonetic_source: Some(s.phonetic_source),
                category: None,
                scene: Some(s.scene),
                example_en: None,
                example_zh: None,
                example_context: s.example_context,
                mother_tip: None,
                image_emoji: None,
                match_level: "L2-confirm".into(),
                tts_available: false,
                tts_url: None,
            }
        }
        _ => return Err(AppError::BadRequest("target_type 非法".into())),
    };

    // 计一次 ask
    if let Some(cid) = &body.child_id {
        crate::logic::record_learning(pool, cid, &result.target_type, &result.target_id, "ask", None, None)
            .await?;
    }

    Ok(Json(json!({ "ok": true, "result": result })))
}

/// 匹配管线主流程（L0 → L1 → L2 → 兜底）
async fn run_pipeline(
    state: &SharedState,
    raw: &str,
    asr_confidence: Option<f64>,
    family_id: Option<&str>,
    child_id: Option<&str>,
) -> AskResponse {
    let pool = &state.pool;
    let normalized = crate::normalize::normalize(raw);

    let matcher = state.matcher.read().await;
    let outcome = matcher.match_query(&normalized, raw);
    drop(matcher);

    let tts_ready = state.inference.ready.read().map(|r| r.tts).unwrap_or(false);

    match outcome {
        Match::Hit(target, level) => {
            let mut result = target.into_ask_result();
            result.match_level = level.to_string();
            match store::enrich_ask_result(pool, result).await {
                Ok(r) => {
                    result = r;
                    // TTS 音频 URL（发音是否可用取决于 TTS 服务）
                    result.tts_available = tts_ready;
                    if tts_ready {
                        result.tts_url = Some(format!("/api/tts/audio?text={}&voice=en_US-lessig-medium&rate=0.8",
                            percent_encoding::utf8_percent_encode(&result.en, percent_encoding::NON_ALPHANUMERIC)));
                    }
                    // 记录 ask 学习动作
                    if let Some(cid) = child_id {
                        let _ = crate::logic::record_learning(
                            pool, cid, &result.target_type, &result.target_id, "ask", None, None,
                        ).await;
                    }
                    AskResponse {
                        status: if tts_ready { "hit" } else { "tts_only_down" }.into(),
                        result: Some(result),
                        candidates: vec![],
                        recognized_text: Some(raw.to_string()),
                        normalized_text: Some(normalized.clone()),
                        unmatched_id: None,
                        message: None,
                    }
                }
                Err(_) => AskResponse {
                    status: "nomatch".into(),
                    result: None,
                    candidates: vec![],
                    recognized_text: Some(raw.to_string()),
                    normalized_text: Some(normalized),
                    unmatched_id: None,
                    message: Some("内部错误，请重试".into()),
                },
            }
        }
        Match::Ambiguous(cands) => {
            let mut candidates = Vec::new();
            for c in cands {
                let mut r = c.into_ask_result();
                r.match_level = "L2-ambiguous".into();
                if let Ok(enriched) = store::enrich_ask_result(pool, r).await {
                    let mut enriched = enriched;
                    enriched.tts_available = tts_ready;
                    candidates.push(enriched);
                }
            }
            AskResponse {
                status: "ambiguous".into(),
                result: None,
                candidates,
                recognized_text: Some(raw.to_string()),
                normalized_text: Some(normalized),
                unmatched_id: None,
                message: Some("你是说哪一个？".into()),
            }
        }
        Match::Miss => {
            // 彻底未命中：相近词推荐 + 文字输入 + 静默写入未命中表（8.8）
            let fam_id = match family_id {
                Some(f) => f.to_string(),
                None => {
                    sqlx::query_scalar::<_, String>("SELECT family_id FROM family LIMIT 1")
                        .fetch_optional(pool)
                        .await
                        .ok()
                        .flatten()
                        .unwrap_or_default()
                }
            };

            let unmatched_id = if fam_id.is_empty() {
                None
            } else {
                logic_unmatched::upsert_unmatched(pool, &fam_id, raw, &normalized, asr_confidence)
                    .await
                    .ok()
            };

            // 相近词推荐：同 category 优先
            let m = state.matcher.read().await;
            let suggested = m.suggest_similar(Some("general"), "", 3);
            drop(m);
            let mut candidates = Vec::new();
            for s in suggested {
                let mut r = s.into_ask_result();
                if let Ok(enriched) = store::enrich_ask_result(pool, r).await {
                    candidates.push(enriched);
                }
            }

            AskResponse {
                status: "nomatch".into(),
                result: None,
                candidates,
                recognized_text: Some(raw.to_string()),
                normalized_text: Some(normalized.clone()),
                unmatched_id,
                message: Some("这个词还没准备好，我记下了".into()),
            }
        }
    }
}

/// 未命中表写入（独立小模块，避免 logic.rs 依赖膨胀）
pub mod logic_unmatched {
    use sqlx::SqlitePool;
    use uuid::Uuid;

    pub async fn upsert_unmatched(
        pool: &SqlitePool,
        family_id: &str,
        raw: &str,
        normalized: &str,
        asr_confidence: Option<f64>,
    ) -> crate::error::AppResult<String> {
        let now = chrono::Utc::now().to_rfc3339();
        let id = Uuid::new_v4().to_string();
        // normalized_text 唯一索引：重复出现走 hit_count+1（8.8 / 8.9）
        let existing = sqlx::query_as::<_, (String,)>(
            "SELECT id FROM unmatched_query WHERE family_id=? AND normalized_text=?",
        )
        .bind(family_id)
        .bind(normalized)
        .fetch_optional(pool)
        .await?;

        match existing {
            Some((uid,)) => {
                sqlx::query(
                    "UPDATE unmatched_query SET hit_count = hit_count + 1, last_seen_at=?, raw_text=? WHERE id=?",
                )
                .bind(&now)
                .bind(raw)
                .bind(&uid)
                .execute(pool)
                .await?;
                Ok(uid)
            }
            None => {
                sqlx::query(
                    "INSERT INTO unmatched_query (id, family_id, raw_text, normalized_text, asr_confidence, hit_count, status, last_seen_at) \
                     VALUES (?,?,?,?,?,1,'pending',?)",
                )
                .bind(&id)
                .bind(family_id)
                .bind(raw)
                .bind(normalized)
                .bind(asr_confidence)
                .bind(&now)
                .execute(pool)
                .await?;
                Ok(id)
            }
        }
    }
}
//! 家庭与孩子：首次引导（6.7）、设置（6.5/11.3/11.4）、模型配置（9.8）

use axum::extract::{Path, State};
use axum::routing::{get, post, put};
use axum::{Json, Router};
use chrono::{Datelike, Local};
use serde::{Deserialize, Serialize};
use serde_json::json;
use sqlx::Row;
use uuid::Uuid;

use crate::error::{AppError, AppResult};
use crate::models::{AgeBand, Child, Family};
use crate::state::SharedState;

pub fn router() -> Router<SharedState> {
    Router::new()
        .route("/api/family/me", get(family_me))
        .route("/api/family/init", post(family_init))
        .route("/api/family/settings", put(family_settings))
        .route("/api/family/child", post(child_create))
        .route("/api/family/child/{child_id}", put(child_update))
        .route("/api/family/child/{child_id}", get(child_get))
}

#[derive(Deserialize)]
struct FamilyInit {
    mother_name: Option<String>,
    child_name: Option<String>,
    child_birthdate: Option<String>, // YYYY-MM-DD
}

#[derive(Serialize)]
struct FamilyView {
    family: Family,
    child: Option<Child>,
    age_band: Option<String>,
    age_months: Option<i64>,
    settings: serde_json::Value,
}

async fn family_me(State(state): State<SharedState>) -> AppResult<Json<serde_json::Value>> {
    let pool = &state.pool;
    // 单家庭：取第一条
    let fam = sqlx::query_as::<_, (String, String, String)>("SELECT family_id, mother_name, settings FROM family LIMIT 1")
        .fetch_optional(pool)
        .await?;
    let Some((family_id, mother_name, settings_json)) = fam else {
        // 未初始化 → 前端进引导页
        return Ok(Json(json!({ "initialized": false })));
    };
    let settings: serde_json::Value = serde_json::from_str(&settings_json).unwrap_or(json!({}));
    let child = sqlx::query_as::<_, (String, String, String, Option<String>, Option<String>, i64)>(
        "SELECT child_id, family_id, child_name, child_birthdate, age_band_override, level FROM child WHERE family_id=? LIMIT 1",
    )
    .bind(&family_id)
    .fetch_optional(pool)
    .await?
    .map(|(child_id, family_id, child_name, child_birthdate, age_band_override, level)| Child {
        child_id,
        family_id,
        child_name,
        child_birthdate,
        age_band_override,
        level,
    });

    let (age_band, age_months) = match &child {
        Some(c) => {
            let band = c
                .age_band_override
                .clone()
                .or_else(|| {
                    AgeBand::from_birthdate(c.child_birthdate.as_deref(), &chrono::Utc::now())
                        .map(|b| b.label().to_string())
                });
            let months = c
                .child_birthdate
                .as_deref()
                .and_then(|bd| {
                    chrono::NaiveDate::parse_from_str(bd, "%Y-%m-%d").ok().map(|d| {
                        let today = chrono::Local::now().date_naive();
                        (today.year() - d.year()) * 12 + (today.month() as i32 - d.month() as i32)
                            + if today.day() >= d.day() { 0 } else { -1 }
                    })
                })
                .map(|m| m as i64);
            (band, months)
        }
        None => (None, None),
    };

    Ok(Json(json!({
        "initialized": true,
        "family": { "family_id": family_id, "mother_name": mother_name },
        "child": child,
        "age_band": age_band,
        "age_months": age_months,
        "settings": settings,
    })))
}

/// 首次启动引导提交（PRD 6.7：孩子生日 → 自动分段）
async fn family_init(State(state): State<SharedState>, Json(body): Json<FamilyInit>) -> AppResult<Json<serde_json::Value>> {
    let pool = &state.pool;
    let family_id = Uuid::new_v4().to_string();
    let child_id = Uuid::new_v4().to_string();
    let now = chrono::Utc::now().to_rfc3339();

    let mut tx = pool.begin().await?;
    sqlx::query("INSERT INTO family (family_id, mother_name, settings, created_at) VALUES (?,?,?,?)")
        .bind(&family_id)
        .bind(body.mother_name.clone().unwrap_or_default())
        .bind(json!({
            "tts_rate": 0.8,
            "audio_only": true,          // A 段默认开启，B 段默认关闭（6.6）
            "screen_limit_min": 5,       // A 段手动关闭纯音频后上限 5 分钟/天（11.3）
            "session_limit_min": 3,
            "bedtime_hour": 21,
        }).to_string())
        .bind(&now)
        .execute(&mut *tx)
        .await?;

    // 推导分段：默认 A 段纯音频；跳过生日默认 B 段（6.7）
    let birthdate = body.child_birthdate.clone();
    let band = AgeBand::from_birthdate(birthdate.as_deref(), &chrono::Utc::now());
    let default_audio_only = band.map(|b| b == AgeBand::A).unwrap_or(false);
    sqlx::query(
        "INSERT INTO child (child_id, family_id, child_name, child_birthdate, age_band_override, level, created_at) VALUES (?,?,?,?,?,?,?)",
    )
    .bind(&child_id)
    .bind(&family_id)
    .bind(body.child_name.clone().unwrap_or_else(|| "宝宝".into()))
    .bind(&birthdate)
    .bind(Option::<String>::None)
    .bind(1)
    .bind(&now)
    .execute(&mut *tx)
    .await?;

    // 按分段修正音频默认值
    if !default_audio_only {
        sqlx::query("UPDATE family SET settings=? WHERE family_id=?")
            .bind(json!({
                "tts_rate": 0.8,
                "audio_only": false,
                "screen_limit_min": 15,  // B 段默认 15 分钟/天（11.3）
                "session_limit_min": 5,
                "bedtime_hour": 21,
            }).to_string())
            .bind(&family_id)
            .execute(&mut *tx)
            .await?;
    }
    tx.commit().await?;

    Ok(Json(json!({
        "ok": true,
        "family_id": family_id,
        "child_id": child_id,
        "age_band": band.map(|b| b.label().to_string()),
        "audio_only": default_audio_only,
    })))
}

#[derive(Deserialize)]
struct SettingsBody {
    settings: serde_json::Value,
}

async fn family_settings(State(state): State<SharedState>, Json(body): Json<SettingsBody>) -> AppResult<Json<serde_json::Value>> {
    let pool = &state.pool;
    let fam: Option<(String,)> = sqlx::query_as("SELECT family_id FROM family LIMIT 1")
        .fetch_optional(pool)
        .await?;
    let Some((family_id,)) = fam else {
        return Err(AppError::NotFound("家庭未初始化".into()));
    };
    sqlx::query("UPDATE family SET settings=? WHERE family_id=?")
        .bind(body.settings.to_string())
        .bind(&family_id)
        .execute(pool)
        .await?;
    Ok(Json(json!({ "ok": true })))
}

#[derive(Deserialize)]
struct ChildCreate {
    child_name: Option<String>,
    child_birthdate: Option<String>,
}

async fn child_create(State(state): State<SharedState>, Json(body): Json<ChildCreate>) -> AppResult<Json<serde_json::Value>> {
    let pool = &state.pool;
    let fam: Option<(String,)> = sqlx::query_as("SELECT family_id FROM family LIMIT 1")
        .fetch_optional(pool)
        .await?;
    let Some((family_id,)) = fam else {
        return Err(AppError::NotFound("家庭未初始化".into()));
    };
    let child_id = Uuid::new_v4().to_string();
    sqlx::query(
        "INSERT INTO child (child_id, family_id, child_name, child_birthdate, level) VALUES (?,?,?,?,1)",
    )
    .bind(&child_id)
    .bind(&family_id)
    .bind(body.child_name.unwrap_or_else(|| "宝宝".into()))
    .bind(&body.child_birthdate)
    .execute(pool)
    .await?;
    Ok(Json(json!({ "ok": true, "child_id": child_id })))
}

#[derive(Deserialize)]
struct ChildUpdate {
    child_name: Option<String>,
    child_birthdate: Option<String>,
    age_band_override: Option<String>,
    level: Option<i64>,
}

async fn child_update(
    State(state): State<SharedState>,
    Path(child_id): Path<String>,
    Json(body): Json<ChildUpdate>,
) -> AppResult<Json<serde_json::Value>> {
    let pool = &state.pool;
    if let Some(name) = &body.child_name {
        sqlx::query("UPDATE child SET child_name=? WHERE child_id=?")
            .bind(name)
            .bind(&child_id)
            .execute(pool)
            .await?;
    }
    if let Some(bd) = &body.child_birthdate {
        sqlx::query("UPDATE child SET child_birthdate=? WHERE child_id=?")
            .bind(bd)
            .bind(&child_id)
            .execute(pool)
            .await?;
    }
    if let Some(band) = &body.age_band_override {
        let band = if band.is_empty() { None } else { Some(band.clone()) };
        sqlx::query("UPDATE child SET age_band_override=? WHERE child_id=?")
            .bind(band)
            .bind(&child_id)
            .execute(pool)
            .await?;
    }
    if let Some(lv) = body.level {
        sqlx::query("UPDATE child SET level=? WHERE child_id=?")
            .bind(lv)
            .bind(&child_id)
            .execute(pool)
            .await?;
    }
    Ok(Json(json!({ "ok": true })))
}

async fn child_get(State(state): State<SharedState>, Path(child_id): Path<String>) -> AppResult<Json<serde_json::Value>> {
    let pool = &state.pool;
    let child = sqlx::query_as::<_, (String, String, String, Option<String>, Option<String>, i64)>(
        "SELECT child_id, family_id, child_name, child_birthdate, age_band_override, level FROM child WHERE child_id=?",
    )
    .bind(&child_id)
    .fetch_optional(pool)
    .await?
    .map(|(child_id, family_id, child_name, child_birthdate, age_band_override, level)| Child {
        child_id,
        family_id,
        child_name,
        child_birthdate,
        age_band_override,
        level,
    });
    let Some(child) = child else {
        return Err(AppError::NotFound("孩子不存在".into()));
    };
    let band = child
        .age_band_override
        .clone()
        .or_else(|| {
            AgeBand::from_birthdate(child.child_birthdate.as_deref(), &chrono::Utc::now())
                .map(|b| b.label().to_string())
        });
    Ok(Json(json!({
        "child": child,
        "age_band": band,
    })))
}
//! 配置加载（env 驱动，PRD 9.9：.env 管理 secret 与服务地址）

use std::env;

#[derive(Debug, Clone)]
pub struct Config {
    /// 监听地址，默认 0.0.0.0:8080
    pub bind_addr: String,
    /// SQLite 文件路径
    pub database_url: String,
    /// 词条 seed 目录（JSON 文件）
    pub seed_dir: String,
    /// 录音与音频缓存根目录
    pub audio_dir: String,
    /// 推理服务地址（HTTP）
    pub tts_url: String,
    pub asr_url: String,
    pub llm_url: String,
    /// 主密钥（用于 API Key envelope 加密；开发默认随机，重启即失效）
    pub master_key: String,
    /// 音频转码可执行文件
    pub ffmpeg_bin: String,
    /// 静态前端目录（PWA 产物）
    pub static_dir: String,
    /// 推理服务调用超时（秒）
    pub svc_timeout_secs: u64,
}

impl Config {
    pub fn from_env() -> Self {
        Self {
            bind_addr: env::var("BIND_ADDR").unwrap_or_else(|_| "0.0.0.0:8080".into()),
            database_url: env::var("DATABASE_URL")
                .unwrap_or_else(|_| "sqlite://data/babyeng.db".into()),
            seed_dir: env::var("SEED_DIR").unwrap_or_else(|_| "data/seed".into()),
            audio_dir: env::var("AUDIO_DIR").unwrap_or_else(|_| "data/audio".into()),
            tts_url: env::var("TTS_URL").unwrap_or_else(|_| "http://127.0.0.1:8101".into()),
            asr_url: env::var("ASR_URL").unwrap_or_else(|_| "http://127.0.0.1:8102".into()),
            llm_url: env::var("LLM_URL").unwrap_or_else(|_| "http://127.0.0.1:8103".into()),
            master_key: env::var("MASTER_KEY").unwrap_or_else(|_| "dev-insecure-key".into()),
            ffmpeg_bin: env::var("FFMPEG_BIN").unwrap_or_else(|_| "ffmpeg".into()),
            static_dir: env::var("STATIC_DIR").unwrap_or_else(|_| "frontend/dist".into()),
            svc_timeout_secs: env::var("SVC_TIMEOUT_SECS")
                .ok()
