      results.push({ page: 'smoke-ask-nomatch', ok: hasBanner > 0 && suggestCount > 0, banner: hasBanner, suggest: suggestCount })
    } catch (e) {
      results.push({ page: 'smoke-ask-nomatch', ok: false, errors: [e.message] })
    }
    await page.close()
  }

