  if (failed.length) {
    console.log(`\nFAILED: ${failed.length}/${results.length}`)
    process.exit(1)
  }
  console.log(`\nALL PASS (${results.length})`)
}

main().catch((e) => {
  console.error(e)
  process.exit(1)
})
