        tokio::task::spawn_blocking(move || {
            let resp = ureq::agent()
                .post(&url)
                .timeout(timeout)
                .send_json(serde_json::json!({ "zh": zh, "schema": "word_lookup" }))
                .map_err(|_| AppError::LlmUnavailable)?;
            if resp.status() != 200 {
                return Err(AppError::LlmUnavailable);
            }
            resp.into_json::<serde_json::Value>()
                .map_err(|_| AppError::LlmUnavailable)
        })
        .await
