         ON CONFLICT(child_id, day) DO UPDATE SET frozen = 1",
    )
    .bind(child_id)
    .bind(&today)
    .execute(pool)
    .await?;
    let id = Uuid::new_v4().to_string();
    let key = format!("freeze_{}", today);
    sqlx::query(
        "INSERT OR IGNORE INTO achievement (id, child_id, type, key, unlocked_at) VALUES (?,?,?,?,?)",
