) -> AppResult<()> {
    let now = Utc::now();
    let id = Uuid::new_v4().to_string();

    // 1. 写明细流水
    sqlx::query(
        "INSERT INTO learning_record (id, child_id, target_type, target_id, action, mother_mark, quiz_result, recorded_at) \
         VALUES (?,?,?,?,?,?,?,?)",
    )
    .bind(&id)
    .bind(child_id)
    .bind(target_type)
    .bind(target_id)
    .bind(action)
    .bind(mother_mark)
    .bind(quiz_result)
    .bind(now.to_rfc3339())
    .execute(pool)
    .await?;

    // 2. 更新 progress（upsert）
    let row =
        sqlx::query("SELECT * FROM progress WHERE child_id=? AND target_type=? AND target_id=?")
            .bind(child_id)
            .bind(target_type)
            .bind(target_id)
            .fetch_optional(pool)
            .await?;

    let (mut learn_count, mut review_count, mut marks_json, mut quiz_json): (
        i64,
        i64,
        String,
        String,
    ) = match row {
        Some(r) => (
            r.try_get("learn_count")?,
            r.try_get("review_count")?,
            r.try_get::<String, _>("last_mother_marks")?,
            r.try_get::<String, _>("last_quiz_results")?,
        ),
        None => (0, 0, "[]".into(), "[]".into()),
