pub async fn month_calendar(pool: &SqlitePool, child_id: &str) -> AppResult<serde_json::Value> {
    let now = Local::now();
    let month = now.format("%Y-%m").to_string();
    let rows = sqlx::query("SELECT day, frozen FROM child_daily WHERE child_id=? AND day LIKE ?")
